CREATE OR REPLACE FUNCTION public.accept_invitation(p_token character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_invite RECORD;
  v_user_email VARCHAR;
BEGIN
  -- 1. Buscar la invitación que coincida y no esté vencida ni aceptada
  SELECT * INTO v_invite
  FROM household_invitations
  WHERE token = p_token
    AND status = 'pending'
    AND expires_at > now()
  FOR UPDATE; -- Bloqueo transaccional para evitar doble uso

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El código de invitación es inválido, ya fue usado o ha expirado.';
  END IF;

  -- (Opcional) Podemos validar que el email invitado coincida con el email del usuario
  -- SELECT email INTO v_user_email FROM auth.users WHERE id = auth.uid();
  -- IF v_user_email != v_invite.email THEN
  --   RAISE EXCEPTION 'Esta invitación no fue enviada a tu correo.';
  -- END IF;

  -- 2. Insertar al usuario como miembro (role: member)
  INSERT INTO household_members (profile_id, household_id, role, status)
  VALUES (auth.uid(), v_invite.household_id, 'member', 'active');

  -- 3. Marcar la invitación como aceptada
  UPDATE household_invitations
  SET status = 'accepted'
  WHERE id = v_invite.id;

  RETURN v_invite.household_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_pet_task(p_household_id uuid, p_pet_task_id uuid)
 RETURNS TABLE(completed_date timestamp with time zone, completed_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_completed_date timestamptz;
  v_completed_by uuid;
BEGIN
  v_member_id := public.assert_active_household_member(p_household_id);

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'No active household member found.';
  END IF;

  UPDATE public.pet_tasks pt
  SET completed = true,
      completed_date = now(),
      completed_by = v_member_id
  FROM public.pets p
  WHERE pt.id = p_pet_task_id
    AND pt.pet_id = p.id
    AND p.household_id = p_household_id
  RETURNING pt.completed_date, pt.completed_by
  INTO v_completed_date, v_completed_by;

  IF v_completed_date IS NULL THEN
    RAISE EXCEPTION 'Pet task was not found for this household.';
  END IF;

  completed_date := v_completed_date;
  completed_by := v_completed_by;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_pet_task(p_household_id uuid, p_pet_task_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_deleted_count integer;
BEGIN
  v_member_id := public.assert_active_household_member(p_household_id);

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'No active household member found.';
  END IF;

  DELETE FROM public.pet_tasks pt
  USING public.pets p
  WHERE pt.id = p_pet_task_id
    AND pt.pet_id = p.id
    AND p.household_id = p_household_id;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  IF v_deleted_count = 0 THEN
    RAISE EXCEPTION 'Pet task was not found for this household.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.reopen_pet_task(p_household_id uuid, p_pet_task_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_updated_count integer;
BEGIN
  v_member_id := public.assert_active_household_member(p_household_id);

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'No active household member found.';
  END IF;

  UPDATE public.pet_tasks pt
  SET completed = false,
      completed_date = null,
      completed_by = null
  FROM public.pets p
  WHERE pt.id = p_pet_task_id
    AND pt.pet_id = p.id
    AND p.household_id = p_household_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  IF v_updated_count = 0 THEN
    RAISE EXCEPTION 'Pet task was not found for this household.';
  END IF;
END;
$function$
